 canvas.addEventListener('pointerdown',e=>{down=e.button===0?{x:e.clientX,y:e.clientY,id:e.pointerId,moved:false,time:performance.now()}:null;});canvas.addEventListener('pointermove',e=>{if(down&&Math.hypot(e.clientX-down.x,e.clientY-down.y)>6)down.moved=true;});canvas.addEventListener('pointercancel',()=>down=null);canvas.addEventListener('pointerup',e=>{const tap=down&&down.id===e.pointerId&&performance.now()-down.time<480&&!down.moved&&!multi&&Math.hypot(e.clientX-down.x,e.clientY-down.y)<=6&&e.button===0;down=null;if(!tap||!document.body.classList.contains('playing'))return;const r=canvas.getBoundingClientRect(),picker=scene.metadata.label49,hit=worldPicking.pick(e.clientX-r.left,e.clientY-r.top),record=worldPicking.isInteraction(hit)?null:picker.resolve(hit);selected=byId.get(String(record?.id));if(!selected){popup.hidden=panel.hidden=true;worldPicking.handle(hit);return;}if(onBoardTap(selected.id)){popup.hidden=panel.hidden=true;return;}onOpen();popup.querySelector('strong').textContent=selected.displayName;popup.dataset.id=selected.id;popup.hidden=false;panel.hidden=true;position(popup,e.clientX,e.clientY);});window.addEventListener('resize',()=>{popup.hidden=true;panel.hidden=true;});document.addEventListener('keydown',e=>{if(e.key==='Escape'){popup.hidden=true;panel.hidden=true;}});
